function PROFILE_OF_BETA(beta):
  if beta < 0 or beta > 1/2:
    return UNDEFINED      # ill-posed regime, no parameter exists
  t <- 1 - sqrt(1 - 2*beta)   # unique root in [0,1]
  return t*t*(1 - t)          # p_min(beta) = minProfile(t)

